def extract(tree):
    rows = tree.where(content_desc="sourceLanguagePicker")
    if not rows:
        raise ValueError("From language picker is absent")
    label = rows[0]["name"]
    if ": " not in label:
        raise ValueError("From language label has unexpected format")
    return label.split(": ", 1)[1]

def extract(tree):
    rows = tree.where(content_desc="targetLanguagePicker")
    if not rows:
        raise ValueError("To language picker is absent")
    label = rows[0]["name"]
    if ": " not in label:
        raise ValueError("To language label has unexpected format")
    return label.split(": ", 1)[1]

